from typing import Protocol, runtime_checkable

@runtime_checkable
class SupportsRead(Protocol):
    def read(self, length: int = ...): ...

class Wrapper:
    def __getattr__(self, name):
        if name == "read":
            return lambda length=None: b"data"
        raise AttributeError(name)

w = Wrapper()
print(f"isinstance(w, SupportsRead): {isinstance(w, SupportsRead)}")
print(f"hasattr(w, 'read'): {hasattr(w, 'read')}")

